# owner: platform
import unittest

from hourglass.rounding import round_span, rounded_labels
from hourglass.parsing import parse_span
from hourglass.models import Span


class RoundSpanTests(unittest.TestCase):
    def test_nearest_step(self):
        self.assertEqual(
            round_span(Span(542, 1027), 15), Span(540, 1020)
        )

    def test_halfway_goes_up(self):
        self.assertEqual(
            round_span(Span(15, 45), 30), Span(30, 60)
        )

    def test_end_of_day_stays(self):
        self.assertEqual(
            round_span(Span(0, 1440), 30), Span(0, 1440)
        )


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:02-17:13")]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_several_spans(self):
        spans = [parse_span("08:58-12:00"), Span(780, 800)]
        self.assertEqual(
            rounded_labels(spans, 30),
            ["09:00-12:00 (3h 0m)", "13:00-13:30 (0h 30m)"]
        )

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])


class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    rounded_labels([Span(0, 60)], step)
                with self.assertRaises(ValueError):
                    round_span(Span(0, 60), step)

    def test_bad_step_with_no_spans(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)
